import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
    // Group that will hold the whole node
    const node = new THREE.Group();

    // ---------- Textured Plane ----------
    const imageUrl = config.assets?.imageUrl;
    const tex = ctx.textureLoader.load(imageUrl);
    // Preserve aspect ratio from source rect (512 x 320)
    const aspect = 512 / 320;
    const planeWidth = 1.6; // arbitrary base width
    const planeHeight = planeWidth / aspect;

    const planeGeometry = new THREE.PlaneGeometry(planeWidth, planeHeight);
    const planeMaterial = new THREE.MeshBasicNodeMaterial({
        map: tex,
        transparent: true
    });
    const planeMesh = new THREE.Mesh(planeGeometry, planeMaterial);
    node.add(planeMesh);

    // ---------- MSDF Text ----------
    const textString = (config.textContent && config.textContent[0]) || "Pricing 3";
    // Assume ctx.fontAtlas provides a method to create a text mesh using MSDF.
    const textMesh = ctx.fontAtlas.createTextMesh({
        text: textString,
        // Atlas region defined in the spec
        atlasIndex: 0,
        sourceRect: { x: 0, y: 0, width: 512, height: 320 },
        // Use display typography (Lora) – size tuned for the plane
        fontStyle: "display",
        // Rough size estimation; will be scaled later if needed
        size: 0.2,
        color: new THREE.Color(config.colors?.ink ?? "#16161d")
    });
    // Slight offset toward the camera to avoid z‑fighting
    textMesh.position.set(0, 0, 0.001);
    node.add(textMesh);

    // ---------- Transform ----------
    const pos = config.scenePlacement?.position ?? [0, 0, 0];
    const rot = config.scenePlacement?.rotation ?? [0, 0, 0];
    const scl = config.scenePlacement?.scale ?? [1, 1, 1];
    node.position.set(pos[0], pos[1], pos[2]);
    node.rotation.set(rot[0], rot[1], rot[2]);
    node.scale.set(scl[0], scl[1], scl[2]);

    // ---------- Cinematic Primitives ----------
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const primitive of config.cinematicPrimitives) {
            const fn = ctx.primitives?.[primitive.name];
            if (typeof fn === "function") {
                fn(node, primitive.params);
            }
        }
    }

    // ---------- Event Handlers ----------
    node.userData.handlers = {};

    // ---------- Cleanup ----------
    const timelines = []; // store any GSAP timelines that might be created in the future
    node.userData.cleanup = () => {
        planeGeometry.dispose();
        planeMaterial.dispose();
        if (tex) tex.dispose();

        if (textMesh) {
            if (textMesh.geometry) textMesh.geometry.dispose();
            if (textMesh.material) textMesh.material.dispose();
        }

        timelines.forEach(t => t.kill());
    };

    return node;
}
